-- DL-07: lịch nghỉ quốc gia (scope QUOC_GIA) của tenant hệ thống trong config.holiday_calendar.
-- SINH TỰ ĐỘNG từ data/seed/config/holiday_calendar_*.csv bằng data/seed/config/sinh_migration.py; không sửa tay.
-- Mã dòng trùng NationalHolidays.idOf để lịch dựng sẵn của CORE-08-04 và dòng trong bảng là một.
-- Chạy bằng mig_config (chủ bảng). FORCE RLS chặn cả chủ bảng nên tạm tắt trong giao dịch của migration.
ALTER TABLE ${flyway:defaultSchema}.holiday_calendar NO FORCE ROW LEVEL SECURITY;

ON CONFLICT (tenant_id, calendar_date) DO UPDATE SET day_kind = EXCLUDED.day_kind, name = EXCLUDED.name,
  scope = EXCLUDED.scope, updated_at = now(), updated_by = EXCLUDED.updated_by,
  row_version = ${flyway:defaultSchema}.holiday_calendar.row_version + 1
WHERE (${flyway:defaultSchema}.holiday_calendar.day_kind, ${flyway:defaultSchema}.holiday_calendar.name, ${flyway:defaultSchema}.holiday_calendar.scope)
  IS DISTINCT FROM (EXCLUDED.day_kind, EXCLUDED.name, EXCLUDED.scope);

-- Ngày đã bỏ khỏi tệp nguồn (đính chính theo văn bản chính thức): xoá, vì lịch không bị bảng khác tham chiếu.
DELETE FROM ${flyway:defaultSchema}.holiday_calendar WHERE tenant_id = '00000000-0000-0000-0000-000000000000'::uuid AND scope = 'QUOC_GIA'
  AND calendar_date NOT IN ('2026-01-01', '2026-01-02', '2026-01-10', '2026-02-16', '2026-02-17', '2026-02-18', '2026-02-19', '2026-02-20', '2026-04-26', '2026-04-27', '2026-04-30', '2026-05-01', '2026-08-22', '2026-08-31', '2026-09-01', '2026-09-02', '2026-11-24', '2027-01-01', '2027-02-04', '2027-02-05', '2027-02-06', '2027-02-07', '2027-02-08', '2027-02-09', '2027-02-10', '2027-04-16', '2027-04-30', '2027-05-01', '2027-09-02', '2027-09-03', '2027-11-24');

ALTER TABLE ${flyway:defaultSchema}.holiday_calendar FORCE ROW LEVEL SECURITY;
